import sys

def main():
    n = int(sys.stdin.read().strip())
    if n == 1:
        print("NO")
    else:
        print("YES")
        current = n
        while current > 24:
            print(f"{current} - {current - 1} = 1")
            current -= 1
        if current < 24:
            print(f"24 - {24 - current} = 24")
        elif current > 24:
            print(f"24 + {current - 24} = 24")

